"use client";

import { useState } from "react";
import type { INewsResult } from "@/interfaces/investigation.interface";
import { ApiBannerCompact } from "./ApiBanner";
import { EmptyHint, Panel, TraceList } from "./Primitives";

export function NewsSearch() {
  const [q, setQ] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<INewsResult | null>(null);

  async function search(e: React.FormEvent) {
    e.preventDefault();
    if (!q.trim()) return;
    setBusy(true);
    setError(null);
    try {
      const res = await fetch(`/api/news?q=${encodeURIComponent(q.trim())}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.error ?? `Request failed (${res.status})`);
      setResult(json as INewsResult);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setResult(null);
    } finally {
      setBusy(false);
    }
  }

  const notice = result?.traces.find((t) => t.notice)?.notice;

  return (
    <div className="space-y-4">
      <div className="rounded-xl border border-border bg-bg-elev p-4">
        <form onSubmit={search} className="flex flex-col gap-2 sm:flex-row">
          <input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder={`A name, a company, a phrase — try "Marc Lou"`}
            className="min-w-0 flex-1 rounded-lg border border-border bg-bg-elev-2 px-3 py-2.5 text-sm text-fg outline-none transition focus:border-accent"
          />
          <button
            type="submit"
            disabled={busy || !q.trim()}
            className="shrink-0 rounded-lg bg-accent px-4 py-2.5 text-sm font-semibold text-white transition hover:brightness-110 disabled:opacity-50"
          >
            {busy ? "Searching…" : "Search news"}
          </button>
        </form>
        {error && <p className="mt-3 text-xs text-danger">{error}</p>}
      </div>

      {!result && !busy && !error && (
        <EmptyHint>
          Search what the press has published about a name. This is the public
          record — the part of someone&apos;s footprint they have least control over.
        </EmptyHint>
      )}

      {result && (
        <Panel
          eyebrow="zenserp"
          title={`News mentioning “${result.query}”`}
          right={<span className="mono text-xs text-fg-dim">{result.items.length} result(s)</span>}
        >
          {notice && <p className="mb-3 text-xs text-warn">{notice}</p>}

          {result.items.length === 0 ? (
            <EmptyHint>{notice ? "No results to show." : "Nothing in the news for that query."}</EmptyHint>
          ) : (
            <ul className="space-y-3">
              {result.items.map((n, i) => (
                <li key={i} className="flex gap-3 border-b border-border/60 pb-3 last:border-0">
                  {n.thumbnail && (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img
                      src={n.thumbnail}
                      alt=""
                      className="h-14 w-14 shrink-0 rounded border border-border object-cover"
                    />
                  )}
                  <div className="min-w-0">
                    <a
                      href={n.link}
                      target="_blank"
                      rel="noreferrer noopener nofollow"
                      className="text-sm font-medium text-accent transition hover:underline"
                    >
                      {n.title}
                    </a>
                    <p className="mono mt-0.5 text-[10px] text-fg-dim">
                      {[n.source, n.date].filter(Boolean).join(" · ")}
                    </p>
                    {n.description && (
                      <p className="mt-1 line-clamp-2 text-xs text-fg-muted">{n.description}</p>
                    )}
                  </div>
                </li>
              ))}
            </ul>
          )}

          <div className="mt-3">
            <ApiBannerCompact product="zenserp" label="News search API" />
          </div>
          <TraceList traces={result.traces} />
        </Panel>
      )}
    </div>
  );
}

import { NextRequest } from "next/server";
import { putBlob } from "@/app/lib/blobStore";
import { readExif } from "@/app/lib/exif";
import { assessExposure } from "@/app/lib/exposure";
import { reverseGeocode } from "@/app/lib/positionstack";
import { resolveOrigin } from "@/app/lib/origin";
import { reverseImageSearch } from "@/app/lib/zenserp";
import type { IImageResult, ITrace } from "@/interfaces/investigation.interface";

export const dynamic = "force-dynamic";

/** Refuse anything large enough to be a denial-of-service rather than a photo. */
const MAX_BYTES = 12 * 1024 * 1024;

/**
 * The chained investigation: read what the file is carrying, turn any embedded
 * coordinates into a street address, and find where else the image has been
 * published — then score how much all of that together gives away.
 */
export async function POST(request: NextRequest) {
  let buffer: Buffer | null = null;
  let source: IImageResult["source"];
  let imageUrl: string | null = null;
  let uploadType = "image/jpeg";
  let uploadNotice: string | null = null;

  const contentType = request.headers.get("content-type") ?? "";

  if (contentType.includes("multipart/form-data")) {
    const form = await request.formData();
    const file = form.get("file");
    if (!(file instanceof File)) {
      return Response.json({ error: "No file was uploaded." }, { status: 400 });
    }
    if (file.size > MAX_BYTES) {
      return Response.json(
        { error: `That file is ${(file.size / 1e6).toFixed(1)} MB; the limit is 12 MB.` },
        { status: 413 }
      );
    }
    buffer = Buffer.from(await file.arrayBuffer());
    source = { kind: "upload", name: file.name || "upload" };
    uploadType = file.type || "image/jpeg";
  } else {
    let body: { url?: string };
    try {
      body = (await request.json()) as { url?: string };
    } catch {
      return Response.json({ error: "Invalid JSON body." }, { status: 400 });
    }
    const raw = body.url?.trim();
    if (!raw) return Response.json({ error: "Provide an image URL." }, { status: 400 });

    let parsed: URL;
    try {
      parsed = new URL(raw);
    } catch {
      return Response.json({ error: `"${raw}" is not a valid URL.` }, { status: 400 });
    }
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
      return Response.json({ error: "Only http and https URLs are supported." }, { status: 400 });
    }
    imageUrl = parsed.toString();
    source = { kind: "url", name: imageUrl };

    // Fetch it ourselves so EXIF works on a remote image too, but don't fail
    // the whole request if the host blocks us — the reverse search still works.
    try {
      const res = await fetch(imageUrl, { cache: "no-store" });
      const len = Number(res.headers.get("content-length") ?? 0);
      if (res.ok && len <= MAX_BYTES) {
        buffer = Buffer.from(await res.arrayBuffer());
      }
    } catch {
      buffer = null;
    }
  }

  const traces: ITrace[] = [];
  const exif = buffer
    ? await readExif(buffer)
    : {
        gps: null,
        takenAt: null,
        camera: { make: null, model: null, lens: null, serial: null },
        software: null,
        dimensions: { width: null, height: null },
        fields: [],
        hasAnyMetadata: false,
      };

  // GPS in the file → a real address, via Positionstack.
  let place = null;
  let nearby: IImageResult["nearby"] = [];
  if (exif.gps) {
    const geo = await reverseGeocode(exif.gps.lat, exif.gps.lon, 4);
    traces.push({
      api: "positionstack",
      label: "Reverse geocode EXIF coordinates",
      url: geo.maskedUrl,
      elapsedMs: geo.elapsedMs,
      status: geo.notice ? 0 : 200,
      notice: geo.notice,
    });
    place = geo.places[0] ?? null;
    nearby = geo.places.slice(1);
  }

  // Zenserp fetches the image itself, so an upload has to be served from
  // somewhere reachable. Park it in the short-lived blob store and hand over
  // that URL — provided this app is actually on the public internet.
  if (!imageUrl && buffer) {
    const origin = resolveOrigin(request);
    if (origin.publiclyReachable) {
      imageUrl = `${origin.origin}/api/image/blob/${putBlob(buffer, uploadType)}`;
    } else {
      uploadNotice = origin.reason;
    }
  }

  let matches: IImageResult["matches"] = [];
  if (imageUrl) {
    const rev = await reverseImageSearch(imageUrl);
    traces.push({
      api: "zenserp",
      label: "Reverse image search",
      url: rev.maskedUrl,
      elapsedMs: rev.elapsedMs,
      status: rev.status,
      notice: rev.notice,
    });
    matches = rev.data ?? [];
  }

  if (uploadNotice) {
    traces.push({
      api: "zenserp",
      label: "Reverse image search",
      url: "—",
      elapsedMs: null,
      status: null,
      notice: uploadNotice,
    });
  }

  const result: IImageResult = {
    source,
    exif,
    place,
    nearby,
    matches,
    exposure: assessExposure(exif, place?.label ?? null, matches.length),
    traces,
  };
  return Response.json(result);
}

import { NextRequest } from "next/server";
import { forwardGeocode } from "@/app/lib/positionstack";
import type { ITrace } from "@/interfaces/investigation.interface";

export const dynamic = "force-dynamic";

/** Property-listing lookup: an address in, coordinates and a normalised record out. */
export async function GET(request: NextRequest) {
  const query = request.nextUrl.searchParams.get("q")?.trim();
  if (!query) {
    return Response.json({ error: "Provide an address or place name." }, { status: 400 });
  }

  const res = await forwardGeocode(query, 5);
  const traces: ITrace[] = [
    {
      api: "positionstack",
      label: "Forward geocode address",
      url: res.maskedUrl,
      elapsedMs: res.elapsedMs,
      status: res.notice ? 0 : 200,
      notice: res.notice,
    },
  ];
  return Response.json({ query, places: res.places, traces });
}

import { NextRequest } from "next/server";
import { assessFraud } from "@/app/lib/fraud";
import { lookupIp, moduleStatus } from "@/app/lib/ipstackLookup";
import { reverseGeocode } from "@/app/lib/positionstack";
import type { IIpResult, ITrace } from "@/interfaces/investigation.interface";

export const dynamic = "force-dynamic";

const isValidIp = (ip: string) =>
  /^(\d{1,3}\.){3}\d{1,3}$/.test(ip) || (ip.includes(":") && /^[0-9a-fA-F:]+$/.test(ip));

/**
 * Risk picture for an address: ipstack for who and where it is, Positionstack
 * to turn its coordinates into somewhere you can actually place on a map.
 */
export async function GET(request: NextRequest) {
  const raw = request.nextUrl.searchParams.get("ip")?.trim();

  // No address given: fall back to the caller's own, which is the useful default.
  let target = raw || "";
  if (!target) {
    const xff = request.headers.get("x-forwarded-for");
    target = xff?.split(",")[0]?.trim() ?? "";
  } else if (!isValidIp(target)) {
    return Response.json(
      { error: `"${target}" is not a valid IPv4 or IPv6 address.` },
      { status: 400 }
    );
  }

  const outcome = await lookupIp(target || null);
  const traces: ITrace[] = [
    {
      api: "ipstack",
      label: outcome.cached ? "IP lookup (cached)" : "IP lookup",
      url: outcome.maskedUrl,
      elapsedMs: outcome.elapsedMs,
      status: outcome.status,
      notice: outcome.notice,
    },
  ];

  if (outcome.notice && !outcome.body.latitude) {
    return Response.json({ error: outcome.notice, traces }, { status: 502 });
  }

  const geo = outcome.body;
  let place = null;
  if (geo.latitude != null && geo.longitude != null) {
    const rev = await reverseGeocode(geo.latitude, geo.longitude, 1);
    traces.push({
      api: "positionstack",
      label: "Reverse geocode IP coordinates",
      url: rev.maskedUrl,
      elapsedMs: rev.elapsedMs,
      status: rev.notice ? 0 : 200,
      notice: rev.notice,
    });
    place = rev.places[0] ?? null;
  }

  const payload: IIpResult = {
    ip: geo.ip ?? target,
    geo,
    fraud: assessFraud(geo, moduleStatus().security),
    place,
    traces,
  };
  return Response.json(payload, { headers: { "cache-control": "no-store" } });
}

import { NextRequest } from "next/server";
import { newsSearch } from "@/app/lib/zenserp";
import type { INewsResult, ITrace } from "@/interfaces/investigation.interface";

export const dynamic = "force-dynamic";

/** What the public record says about a name. */
export async function GET(request: NextRequest) {
  const query = request.nextUrl.searchParams.get("q")?.trim();
  if (!query) {
    return Response.json({ error: "Provide a name or phrase to search for." }, { status: 400 });
  }
  if (query.length > 120) {
    return Response.json({ error: "Query is too long (120 characters max)." }, { status: 400 });
  }

  const res = await newsSearch(query);
  const traces: ITrace[] = [
    {
      api: "zenserp",
      label: "News search",
      url: res.maskedUrl,
      elapsedMs: res.elapsedMs,
      status: res.status,
      notice: res.notice,
    },
  ];

  const payload: INewsResult = { query, items: res.data ?? [], traces };
  return Response.json(payload, { headers: { "cache-control": "no-store" } });
}

import { NextRequest } from "next/server";
import { BLOB_TTL_MS, getBlob } from "@/app/lib/blobStore";

export const dynamic = "force-dynamic";

/**
 * Serves an uploaded image for exactly as long as a reverse image search needs
 * it. Marked noindex so the temporary URL can't end up in a search index — this
 * is a privacy tool, and the image belongs to whoever uploaded it.
 */
export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const entry = getBlob(id);

  if (!entry) {
    return new Response("Not found or expired.", { status: 404 });
  }

  return new Response(new Uint8Array(entry.bytes), {
    headers: {
      "content-type": entry.type,
      "content-length": String(entry.bytes.length),
      "cache-control": `private, max-age=${Math.floor(BLOB_TTL_MS / 1000)}`,
      "x-robots-tag": "noindex, nofollow, noarchive",
    },
  });
}

